101	+uint32_t lv_sifli_epic_dbg_cyc(void)
102	+{
103	+    /* Cortex-M33 DWT cycle counter. Lazy-enable TRCENA + CYCCNTENA. */
104	+    static int inited;
105	+    volatile uint32_t * demcr = (volatile uint32_t *)0xE000EDFC;
106	+    volatile uint32_t * dwt_ctrl = (volatile uint32_t *)0xE0001000;
107	+    volatile uint32_t * dwt_cyc = (volatile uint32_t *)0xE0001004;
108	+
109	+    if(!inited) {
110	+        inited = 1;
111	+        *demcr |= (1u << 24);
112	+        *dwt_ctrl |= 1u;
113	+    }
114	+    return *dwt_cyc;
115	+}
