177	
178	static int32_t _epic_evaluate(lv_draw_unit_t * draw_unit, lv_draw_task_t * task)
179	{
180	    LV_UNUSED(draw_unit);
181	
182	    if(task->target_layer == NULL) {
183	        return 0;
184	    }
185	
186	    if(!lv_epic_cf_supported(task->target_layer->color_format, 0)) {
187	        return 0;
188	    }
189	
190	    switch(task->type) {
191	        case LV_DRAW_TASK_TYPE_FILL: {
192	                const lv_draw_fill_dsc_t * draw_dsc = (const lv_draw_fill_dsc_t *)task->draw_dsc;
193	
194	                if(task->target_layer == NULL) {
195	                    return 0;
196	                }
197	
198	                /* EPIC doesn't support rounded corners */
199	                if(draw_dsc->radius != 0) {
200	                    return 0;
201	                }
202	
203	                /* Check gradient support */
204	                if(draw_dsc->grad.dir != LV_GRAD_DIR_NONE) {
205	                    if(draw_dsc->grad.dir != LV_GRAD_DIR_HOR && draw_dsc->grad.dir != LV_GRAD_DIR_VER) {
206	                        return 0;
207	                    }
208	
209	                    /* Only support 2-stop gradients */
210	                    if(draw_dsc->grad.stops_count != 2) {
211	                        return 0;
212	                    }
213	
214	                    /* Check if output format supports gradient */
215	                    lv_layer_t * target_layer = task->target_layer;
216	                    if(target_layer) {
217	                        lv_color_format_t dest_cf = target_layer->color_format;
218	                        uint32_t epic_cf = lv_img_cf_to_epic_cf(dest_cf);
219	                        if(!EPIC_SUPPROT_OUT_FORMAT(epic_cf)) {
220	                            return 0;
221	                        }
222	                    }
223	                }
224	
225	                if(task->preference_score > 70) {
226	                    task->preference_score = 70;
227	                    task->preferred_draw_unit_id = DRAW_UNIT_ID_SIFLI_EPIC;
228	                }
229	                return 1;
230	            }
231	
232	        case LV_DRAW_TASK_TYPE_IMAGE: {
233	                const lv_draw_image_dsc_t * draw_dsc = (const lv_draw_image_dsc_t *)task->draw_dsc;
234	
235	                if(draw_dsc->src == NULL) {
236	                    return 0;
237	                }
238	
239	                if(draw_dsc->clip_radius != 0) {
240	                    return 0;
241	                }
242	
243	                if(draw_dsc->blend_mode != LV_BLEND_MODE_NORMAL) {
244	                    return 0;
245	                }
246	
247	                /* Check if recolor is used */
248	                bool has_recolor = (draw_dsc->recolor_opa != LV_OPA_TRANSP);
249	                if(has_recolor) {
250	                    return 0;
251	                }
252	
253	                /* Check if transform is used */
254	                bool has_transform = (draw_dsc->rotation != 0 ||
255	                                      draw_dsc->scale_x != LV_SCALE_NONE ||
256	                                      draw_dsc->scale_y != LV_SCALE_NONE);
257	
258	                /* Check color format support */
259	                if(!lv_epic_cf_supported(draw_dsc->header.cf, draw_dsc->header.flags)) {
260	                    return 0;
261	                }
262	
263	                /* RGB565A8 with transform is not supported */
264	                if((LV_COLOR_FORMAT_RGB565A8 == draw_dsc->header.cf) && has_transform) {
265	                    return 0;
266	                }
267	
268	                if(task->preference_score > 80) {
269	                    task->preference_score = 80;
270	                    task->preferred_draw_unit_id = DRAW_UNIT_ID_SIFLI_EPIC;
271	                }
272	                return 1;
273	            }
274	
275	        case LV_DRAW_TASK_TYPE_BORDER: {
276	                const lv_draw_border_dsc_t * draw_dsc = (const lv_draw_border_dsc_t *)task->draw_dsc;
277	
278	                if(draw_dsc->radius != 0) {
279	                    return 0;
280	                }
281	
282	                if(task->preference_score > 90) {
283	                    task->preference_score = 90;
284	                    task->preferred_draw_unit_id = DRAW_UNIT_ID_SIFLI_EPIC;
285	                }
286	                return 1;
287	            }
288	
289	#ifdef EPIC_SUPPORT_A8
290	        case LV_DRAW_TASK_TYPE_LABEL: {
291	                const lv_draw_label_dsc_t * draw_dsc = (const lv_draw_label_dsc_t *)task->draw_dsc;
292	                lv_layer_t * target_layer = task->target_layer;
293	
294	                if(target_layer == NULL) {
295	                    return 0;
296	                }
297	
298	                if(draw_dsc->font == NULL || draw_dsc->text == NULL || draw_dsc->text[0] == '\0') {
299	                    return 0;
300	                }
301	
302	                if(_epic_label_has_vector_glyph(draw_dsc)) {
303	                    return 0;
304	                }
305	
306	                if(!lv_epic_cf_supported(target_layer->color_format, 0)) {
307	                    return 0;
308	                }
309	
310	                if(task->preference_score > 95) {
311	                    task->preference_score = 95;
312	                    task->preferred_draw_unit_id = DRAW_UNIT_ID_SIFLI_EPIC;
313	                }
314	                return 1;
315	            }
316	#endif
317	
318	        case LV_DRAW_TASK_TYPE_LAYER: {
319	                const lv_draw_image_dsc_t * draw_dsc = (const lv_draw_image_dsc_t *)task->draw_dsc;
320	                lv_layer_t * layer_to_draw = (lv_layer_t *)draw_dsc->src;
321	
322	                if(layer_to_draw == NULL) {
323	                    return 0;
324	                }
325	
326	                if(layer_to_draw->draw_buf == NULL) {
327	                    return 0;
328	                }
329	
330	                /* Check if recolor is used */
331	                bool has_recolor = (draw_dsc->recolor_opa != LV_OPA_TRANSP);
332	                if(has_recolor) {
333	                    return 0;
334	                }
335	
336	                /* Check if transform is used */
337	                bool has_transform = (draw_dsc->rotation != 0 ||
338	                                      draw_dsc->scale_x != LV_SCALE_NONE ||
339	                                      draw_dsc->scale_y != LV_SCALE_NONE);
340	
341	                /* Check color format support */
342	                if(!lv_epic_cf_supported(layer_to_draw->color_format, 0)) {
343	                    return 0;
344	                }
345	
346	                /* RGB565A8 with transform is not supported */
347	                if((LV_COLOR_FORMAT_RGB565A8 == layer_to_draw->color_format) && has_transform) {
348	                    return 0;
349	                }
350	
351	                if(task->preference_score > 80) {
352	                    task->preference_score = 80;
353	                    task->preferred_draw_unit_id = DRAW_UNIT_ID_SIFLI_EPIC;
354	                }
355	                return 1;
356	            }
357	
358	        default:
359	            return 0;
360	    }
361	
362	    return 0;
363	}
364	
365	static int32_t _epic_dispatch(lv_draw_unit_t * draw_unit, lv_layer_t * layer)
366	{
367	    lv_draw_sifli_epic_unit_t * draw_epic_unit = (lv_draw_sifli_epic_unit_t *)draw_unit;
368	
369	    /* Try to get a ready to draw task */
370	    lv_draw_task_t * task = lv_draw_get_next_available_task(layer, NULL, DRAW_UNIT_ID_SIFLI_EPIC);
371	
372	    if(task == NULL) {
373	        return LV_DRAW_UNIT_IDLE;
374	    }
375	
376	    /* Return immediately if EPIC is busy */
377	    if(draw_epic_unit->task_act) {
378	        return 0;
379	    }
380	
381	    /* Let the SW unit draw this task if not preferred for EPIC */
382	    if(task->preferred_draw_unit_id != DRAW_UNIT_ID_SIFLI_EPIC) {
383	        return LV_DRAW_UNIT_IDLE;
384	    }
385	
386	    /* Allocate buffer for layer */
387	    if(lv_draw_layer_alloc_buf(layer) == NULL) {
388	        EPIC_ASSERT_MSG(false, "EPIC: Failed to allocate layer draw buffer");
389	        return LV_DRAW_UNIT_IDLE;
390	    }
391	
392	    /* Mark task as in progress */
393	    task->state = LV_DRAW_TASK_STATE_IN_PROGRESS;
394	    task->draw_unit = &draw_epic_unit->base_unit;
395	
396	#if LV_USE_SIFLI_EPIC_DRAW_THREAD
397	    if(epic_dispatch_log_cnt < 8) {
398	        LV_LOG_WARN("EPIC dispatch[%u]: type=%d inited=%d",
399	                    (unsigned int)epic_dispatch_log_cnt,
400	                    (int)task->type,
401	                    draw_epic_unit->inited ? 1 : 0);
402	        epic_dispatch_log_cnt++;
403	    }
404	
405	    draw_epic_unit->task_act = task;
406	    /* Let the render thread work */
407	    if(draw_epic_unit->inited) {
408	        lv_thread_sync_signal(&draw_epic_unit->sync);
409	    }
410	#else
411	    draw_epic_unit->task_act = task;
412	    /* Execute drawing immediately */
413	    _epic_execute_drawing(draw_epic_unit);
414	
415	    draw_epic_unit->task_act->state = LV_DRAW_TASK_STATE_FINISHED;
416	    draw_epic_unit->task_act = NULL;
417	
418	    /* Request new dispatching */
419	    lv_draw_dispatch_request();
420	#endif
421	
422	    return 1;
423	}
