425	static int32_t _epic_delete(lv_draw_unit_t * draw_unit)
426	{
427	#if LV_USE_SIFLI_EPIC_DRAW_THREAD
428	    lv_draw_sifli_epic_unit_t * draw_epic_unit = (lv_draw_sifli_epic_unit_t *)draw_unit;
429	
430	    draw_epic_unit->exit_status = true;
431	
432	    if(draw_epic_unit->inited) {
433	        lv_thread_sync_signal(&draw_epic_unit->sync);
434	    }
435	
436	    return lv_thread_delete(&draw_epic_unit->thread);
437	#else
438	    LV_UNUSED(draw_unit);
439	    return 0;
440	#endif
441	}
442	
443	static void _epic_execute_drawing(lv_draw_sifli_epic_unit_t * u)
444	{
445	    lv_draw_task_t * task = u->task_act;
446	    lv_layer_t * layer = task->target_layer;
447	
448	    /* Wait for previous operation to complete */
449	    lv_epic_wait();
450	
451	    if(layer && layer->draw_buf) {
452	        lv_area_t draw_area;
453	
454	        if(lv_area_intersect(&draw_area, &task->_real_area, &task->clip_area)) {
455	            lv_area_move(&draw_area, -layer->buf_area.x1, -layer->buf_area.y1);
456	            lv_draw_buf_flush_cache(layer->draw_buf, &draw_area);
457	        }
458	    }
459	
460	    /* Execute based on task type */
461	    switch(task->type) {
462	        case LV_DRAW_TASK_TYPE_BORDER:
463	            lv_draw_sifli_epic_border(task);
464	            break;
465	
466	        case LV_DRAW_TASK_TYPE_LABEL:
467	            lv_draw_sifli_epic_label(task);
468	            break;
469	
470	        case LV_DRAW_TASK_TYPE_FILL:
471	            lv_draw_sifli_epic_fill(task);
472	            break;
473	
474	        case LV_DRAW_TASK_TYPE_IMAGE:
475	            lv_draw_sifli_epic_img(task);
476	            break;
477	
478	        case LV_DRAW_TASK_TYPE_LAYER:
479	            lv_draw_sifli_epic_layer(task);
480	            break;
481	
482	        default:
483	            break;
484	    }
485	
486	    /* Wait for operation to complete */
487	    lv_epic_wait();
488	
489	    if(layer && layer->draw_buf) {
490	        lv_area_t draw_area;
491	
492	        if(lv_area_intersect(&draw_area, &task->_real_area, &task->clip_area)) {
493	            lv_area_move(&draw_area, -layer->buf_area.x1, -layer->buf_area.y1);
494	            lv_draw_buf_invalidate_cache(layer->draw_buf, &draw_area);
495	        }
496	    }
497	}
