508	#if LV_USE_SIFLI_EPIC_DRAW_THREAD
509	static void _epic_render_thread_cb(void * ptr)
510	{
511	    lv_draw_sifli_epic_unit_t * u = ptr;
512	
513	    lv_thread_sync_init(&u->sync);
514	    u->inited = true;
515	
516	    if(!epic_thread_start_logged) {
517	        LV_LOG_WARN("EPIC render thread started");
518	        epic_thread_start_logged = true;
519	    }
520	
521	    while(1) {
522	        /* Wait for sync if there is no task set */
523	        while(u->task_act == NULL) {
524	            if(u->exit_status) {
525	                break;
526	            }
527	            lv_thread_sync_wait(&u->sync);
528	        }
529	
530	        if(u->exit_status) {
531	            break;
532	        }
533	
534	        if(epic_render_start_log_cnt < 8) {
535	            LV_LOG_WARN("EPIC render start[%u]: type=%d",
536	                        (unsigned int)epic_render_start_log_cnt,
537	                        (int)u->task_act->type);
538	            epic_render_start_log_cnt++;
539	        }
540	
541	        _epic_execute_drawing(u);
542	
543	        if(epic_render_done_log_cnt < 8) {
544	            LV_LOG_WARN("EPIC render done[%u]: type=%d",
545	                        (unsigned int)epic_render_done_log_cnt,
546	                        (int)u->task_act->type);
547	            epic_render_done_log_cnt++;
548	        }
549	
550	        /* Signal the ready state to dispatcher */
551	        u->task_act->state = LV_DRAW_TASK_STATE_FINISHED;
552	
553	        /* Cleanup */
554	        u->task_act = NULL;
555	
556	        /* Request new dispatching */
557	        lv_draw_dispatch_request();
558	    }
559	
560	    u->inited = false;
561	    lv_thread_sync_delete(&u->sync);
562	}
563	#endif
