263	static void epic_xfer_cplt_callback(EPIC_HandleTypeDef * epic)
264	{
265	    if(epic_irq_log_cnt < 8) {
266	        LV_LOG_WARN("EPIC irq done[%u]: state=%d",
267	                    (unsigned int)epic_irq_log_cnt,
268	                    (int)epic->State);
269	        epic_irq_log_cnt++;
270	    }
271	
272	    lv_epic_osa_thread_sync_signal_isr();
273	
274	    if(epic_async_cb != NULL) {
275	        lv_epic_cplt_cbk cb = epic_async_cb;
276	        epic_async_cb = NULL;
277	        cb(epic);
278	    }
279	}
280	
281	static HAL_StatusTypeDef epic_wait_async_result(HAL_StatusTypeDef start_status)
282	{
283	    if(start_status != HAL_OK) {
284	        LV_LOG_WARN("EPIC start failed: status=%d", (int)start_status);
285	        epic_start_failed_cleanup();
286	        return start_status;
287	    }
288	
289	    lv_epic_wait();
290	    return HAL_OK;
291	}
