293	static HAL_StatusTypeDef epic_prepare_start(EPIC_HandleTypeDef * epic,
294	                                            lv_epic_cplt_cbk cb)
295	{
296	    if(epic == NULL) {
297	        return HAL_ERROR;
298	    }
299	
300	    if(lv_epic_is_busy()) {
301	        lv_epic_wait();
302	    }
303	
304	    epic_async_cb = cb;
305	    epic->XferCpltCallback = epic_xfer_cplt_callback;
306	    lv_epic_run();
307	    if(epic_hw_start_log_cnt < 8) {
308	        LV_LOG_WARN("EPIC hw start[%u]: state=%d",
309	                    (unsigned int)epic_hw_start_log_cnt,
310	                    (int)epic->State);
311	        epic_hw_start_log_cnt++;
312	    }
313	    return HAL_OK;
314	}
