156	bool lv_epic_is_busy(void)
157	{
158	    if(!epic_initialized) {
159	        return false;
160	    }
161	
162	    if(epic_handle.State == HAL_EPIC_STATE_BUSY) {
163	        return true;
164	    }
165	
166	#ifdef HAL_EZIP_MODULE_ENABLED
167	    if(ezip_handle.State == HAL_EZIP_STATE_BUSY) {
168	        return true;
169	    }
170	#endif
171	
