175	bool lv_epic_is_hardware_active(void)
176	{
177	    if(!epic_initialized || epic_handle.Instance == NULL) {
178	        return false;
179	    }
180	
181	    /* Only IA_BUSY reflects in-flight GPU ops. HAL State==BUSY can outlive HW
182	     * when EOF IRQ is not serviced (NuttX); polling completion fixes that. */
183	    if((epic_handle.Instance->STATUS & EPIC_STATUS_IA_BUSY_Msk) != 0U) {
184	        return true;
185	    }
186	
187	#ifdef HAL_EZIP_MODULE_ENABLED
188	    if(ezip_handle.State == HAL_EZIP_STATE_BUSY) {
189	        return true;
190	    }
191	#endif
192	
193	    return false;
194	}
