196	void lv_epic_poll_pending_completion(void)
197	{
198	    EPIC_HandleTypeDef * epic = lv_epic_get_handle();
199	
200	    if(epic == NULL || epic->Instance == NULL) {
201	        return;
202	    }
203	
204	    if(epic->IntXferCpltCallback == NULL && epic->XferCpltCallback == NULL) {
205	        return;
206	    }
207	
208	    uint32_t eof = epic->Instance->EOF_IRQ;
209	    bool irq_pending = ((eof & EPIC_EOF_IRQ_IRQ_STATUS_Msk) != 0U)
210	                       || ((eof & EPIC_EOF_IRQ_IRQ_CAUSE_Msk) != 0U);
211	    bool hw_idle = ((epic->Instance->STATUS & EPIC_STATUS_IA_BUSY_Msk) == 0U);
212	
213	    if(irq_pending || hw_idle) {
214	        HAL_EPIC_IRQHandler(epic);
215	    }
216	}
