223	void lv_epic_gpu_check_done(void)
224	{
225	#if LV_USE_NUTTX
226	    /* NuttX uses sync HAL (EPIC_WaitDone inside HAL); no async OSA wait. */
227	    return;
228	#else
229	    /* SiFli drv_gpu_check_done(): ensure async IT completed */
230	    if(epic_gpu_token != 0U && !lv_epic_is_hardware_active()) {
231	        return;
232	    }
233	
234	    lv_epic_poll_pending_completion();
235	    if(lv_epic_is_hardware_active()) {
236	        lv_epic_wait();
237	    }
238	    lv_epic_reconcile_done(lv_epic_get_handle());
239	#endif
240	}
