342	
343	/* operation: 0 clean, 1 clean+invalidate, 2 invalidate. Keep the original
344	 * cache operations for cached/unknown memory, including unaligned boundaries.
345	 */
346	static void epic_cache_maintain(const void * data, uint32_t size, unsigned operation)
347	{
348	    if(data == NULL || size == 0) return;
349	    bool required = lv_epic_is_cached_ram((uint32_t)(uintptr_t)data, size);
350	#if defined(CONFIG_MYVENDOR_LVGL_BENCH)
351	    cache_stats.requested_bytes += size;
352	    if(!cache_filter_enabled) required = true;
353	    if(!required) {
354	        cache_stats.skipped_calls++;
355	        cache_stats.skipped_bytes += size;
356	    }
357	    else if(operation == 0) cache_stats.clean_calls++;
358	    else if(operation == 1) cache_stats.flush_calls++;
359	    else cache_stats.invalidate_calls++;
360	#endif
361	    if(!required) {
362	        /* Non-cacheable does not mean writes have reached the EPIC bus yet.
363	         * Preserve the ordering barrier supplied by the cache primitives. */
364	        __DSB();
365	        return;
366	    }
367	#ifdef CONFIG_ARCH_DCACHE
368	    uintptr_t start = (uintptr_t)data;
369	    if(operation == 0) up_clean_dcache(start, start + size);
370	    else if(operation == 1) up_flush_dcache(start, start + size);
371	    else up_invalidate_dcache(start, start + size);
372	#endif
373	}
374	
375	void lv_epic_clean_invalidate_cache_range(const void * data, uint32_t size)
376	{
377	    epic_cache_maintain(data, size, 1);
378	}
379	#endif
380	
381	void lv_epic_flush_cache_range(const void * data, uint32_t size)
382	{
383	    if(data == NULL || size == 0U) {
384	        return;
385	    }
386	
387	#if defined(__ZEPHYR__)
388	    (void)arch_dcache_flush_range((void *)data, size);
389	#elif LV_USE_NUTTX
390	    epic_cache_maintain(data, size, 0);
391	#else
392	    (void)mpu_dcache_clean((void *)data, size);
393	#endif
394	}
395	
396	void lv_epic_invalidate_cache_range(const void * data, uint32_t size)
397	{
398	    if(data == NULL || size == 0U) {
399	        return;
400	    }
401	
402	#if defined(__ZEPHYR__)
403	    (void)arch_dcache_invd_range((void *)data, size);
404	#elif LV_USE_NUTTX
405	    epic_cache_maintain(data, size, 2);
406	#else
407	    (void)mpu_dcache_invalidate((void *)data, size);
408	#endif
409	}
