513	HAL_StatusTypeDef lv_epic_cont_blend(EPIC_LayerConfigTypeDef * input_layers, uint8_t input_layer_cnt,
514	                                      EPIC_LayerConfigTypeDef * output_layer)
515	{
516	    EPIC_HandleTypeDef * epic = lv_epic_get_handle();
517	    EPIC_LayerConfigTypeDef * fg_layer;
518	    EPIC_LayerConfigTypeDef * mask_layer;
519	    HAL_StatusTypeDef ret;
520	
521	    if(epic == NULL || input_layers == NULL || output_layer == NULL || input_layer_cnt < 2) {
522	        return HAL_ERROR;
523	    }
524	
525	    fg_layer = &input_layers[1];
526	    mask_layer = (input_layer_cnt > 2) ? &input_layers[2] : NULL;
527	
528	    if(!epic_cont_mode) {
529	        if(epic_prepare_start(epic, NULL) != HAL_OK) {
530	            return HAL_ERROR;
531	        }
532	        lv_epic_flush_layers_cache(input_layers, input_layer_cnt, output_layer);
533	
534	        ret = HAL_EPIC_ContBlendStart(epic, fg_layer, mask_layer, output_layer);
535	        if(ret == HAL_OK) {
536	            epic_cont_mode = true;
537	        }
538	        else {
539	            lv_epic_osa_set_idle();
540	        }
541	        return ret;
542	    }
543	
544	    if(fg_layer->data != NULL && fg_layer->data_size > 0U) {
545	        lv_epic_flush_cache_range(fg_layer->data, fg_layer->data_size);
546	    }
