10	/* Match system_bf0_ap.c:mpu_config(). Only skip ranges wholly contained in
11	 * a known non-cacheable RAM region; unknown/overflowing ranges stay conservative.
12	 * Keep this list in sync if the board MPU layout changes.
13	 */
14	static inline bool lv_epic_sf32lb52_uncached_range(uint32_t start, uint32_t size)
15	{
16	    if(size == 0 || size - 1 > UINT32_MAX - start) return false;
17	    uint32_t last = start + size - 1;
18	    return (start >= 0x00010000U && last <= 0x0002ffffU) ||
19	           (start >= 0x20000000U && last <= 0x2027ffffU) ||
20	           (start >= 0x203fc000U && last <= 0x204fffffU) ||
21	           (start >= 0x20bfc000U && last <= 0x20cbffffU);
22	}
