  (CONFIG_LCD_HOR_RES_MAX * CONFIG_MYVENDOR_LCD_DISP_STRIP_ROWS * 2u)

/* LCDC/EPIC/coredump 共用的固定 HCPU SRAM 双条带。显式放在 .bss，避免
