static uint8_t g_lcd_sram_buf_a[MYVENDOR_LCD_SRAM_BUF_BYTES]
    __attribute__((aligned(LV_DRAW_BUF_ALIGN)));
static uint8_t g_lcd_sram_buf_b[MYVENDOR_LCD_SRAM_BUF_BYTES]
    __attribute__((aligned(LV_DRAW_BUF_ALIGN)));

typedef struct
{
  lv_draw_buf_t draw1;
