  void         *sram_px2;
  uint32_t      sram_bytes;
} lv_myvendor_lcd_dsc_t;

/* Benchmark-only: skip the real LCDC DMA entirely (pure render timing). */
static bool s_skip_flush;

void lv_myvendor_lcd_set_skip_flush(bool skip)
{
  s_skip_flush = skip;
}

