105	    area.y1 = top_side ? inner_area->y1 : outer_area->y1;
106	    area.y2 = bottom_side ? inner_area->y2 : outer_area->y2;
107	    if(left_side && area.x1 <= area.x2 && area.y1 <= area.y2) {
108	        draw_fill_part(task, &area, dsc);
109	    }
110	
111	    /* Right */
112	    area.x1 = inner_area->x2 + 1;
113	    area.x2 = outer_area->x2;
114	    if(right_side && area.x1 <= area.x2 && area.y1 <= area.y2) {
115	        draw_fill_part(task, &area, dsc);
